new:
bool IsEliteRefine(DWORD refineSet)
{
	// MT2009_PLUS_SEONPYEONG_ELITE_V1 (elite sets): Seon-Pyeong's (BLACKSMITH2_MOB) refine sets - a +9 piece dragged onto him becomes the next
	// item (the pl-wiki). 501 / 530 the package's; 39900-39999 the fixed recipes of refine_global.sql (the owner's
	// sheet: weapons 65 -> 80, armours / boots -> 80, weapons 80 -> 87-105, weapons / armours 105 -> cyanite,
	// tools/refineglobal/gen_refineglobal.py ELITE - keep the range in step with it). No other smith, no scroll.
	return refineSet == 501 || refineSet == 530 || (refineSet >= 39900 && refineSet <= 39999);
}
